interface Formatter {
    private String normalize(String s) {
        return s.trim().toUpperCase();
    }
    default String label(String s) {
        return "<" + normalize(s) + ">";
    }
}
class Loud implements Formatter {
    @Override
    public String label(String s) {
        return Formatter.super.label(s) + ":" + s.length();
    }
}
public class Main {
    public static void main(String[] args) {
        Formatter f = new Loud();
        System.out.print(f.label(" x "));
    }
}

interface Util {
    private static String prefix() {
        return "P";
    }
    static String make(String s) {
        return prefix() + s;
    }
    default String instance(String s) {
        return prefix() + ":" + s;
    }
}
class Impl implements Util { }

public class Main {
    public static void main(String[] args) {
        System.out.print(Util.make("X") + ":");
        System.out.print(new Impl().instance("Y"));
    }
}

record Score(String name, int point) {
    Score {
        name = name.trim();
        point = switch (point) {
            case -1 -> 0;
            default -> point > 100 ? 100 : point;
        };
    }
    String label() {
        return name + "=" + point;
    }
}
public class Main {
    public static void main(String[] args) {
        Score a = new Score(" A ", 120);
        Score b = new Score("B", -1);
        System.out.print(a.label() + ":" + b.label());
    }
}

