interface Named {
    default String id() { return "I"; }
}
abstract class Parent {
    public String id() { return "P"; }
    abstract int level();
}
class Child extends Parent implements Named {
    @Override
    int level() {
        return id().length();
    }
}
public class Main {
    public static void main(String[] args) {
        Named n = new Child();
        Parent p = (Parent) n;
        System.out.print(n.id() + ":" + p.level());
    }
}

